const item = $input.first().json;
return [{
  json: {
    title: item.title || '',
    link: item.link || '',
    pubDate: item.pubDate || item.isoDate || '',
    categories: item.categories || [],
    snippet: item.contentSnippet || item['content:encodedSnippet'] || item.content || '',
    author: item.creator || item.author || item['dc:creator'] || '',
  }
}];

const jinaResponse = $input.first().json;
const rssData = $('Normalize RSS Data').first().json;

// Extract article content - handle different response shapes
let articleContent = '';
if (typeof jinaResponse === 'string') {
  articleContent = jinaResponse;
} else if (jinaResponse.data && typeof jinaResponse.data === 'string') {
  articleContent = jinaResponse.data;
} else if (jinaResponse.data && jinaResponse.data.content) {
  articleContent = jinaResponse.data.content;
} else if (jinaResponse.body) {
  articleContent = jinaResponse.body;
} else {
  const { binary, ...rest } = jinaResponse;
  articleContent = JSON.stringify(rest);
}

// Extract image URLs from the article content
// Looks for markdown images ![alt](url), HTML <img src="url">, and bare image URLs
const imageUrls = [];
const seen = new Set();

// Markdown images: ![...](url)
const mdImgRegex = /!\[([^\]]*)\]\(([^)]+)\)/g;
let m;
while ((m = mdImgRegex.exec(articleContent)) !== null) {
  const url = m[2].trim();
  if (!seen.has(url)) { seen.add(url); imageUrls.push(url); }
}

// HTML imgs: <img ... src="url" ...>
const htmlImgRegex = /<img[^>]+src=["']([^"']+)["'][^>]*>/gi;
while ((m = htmlImgRegex.exec(articleContent)) !== null) {
  const url = m[1].trim();
  if (!seen.has(url)) { seen.add(url); imageUrls.push(url); }
}

// Filter out tiny icons, tracking pixels, avatars, logos
const filtered = imageUrls.filter(url => {
  const lower = url.toLowerCase();
  if (lower.includes('avatar') || lower.includes('logo') || lower.includes('icon') || lower.includes('favicon')) return false;
  if (lower.includes('tracking') || lower.includes('pixel') || lower.includes('1x1')) return false;
  if (lower.includes('gravatar.com')) return false;
  if (lower.match(/\.(svg|gif)$/i)) return false;
  // Must be http(s) URL
  if (!lower.startsWith('http')) return false;
  return true;
});

// Truncate very long articles to avoid token limits
if (articleContent.length > 15000) {
  articleContent = articleContent.substring(0, 15000) + '\n\n[Content truncated]';
}

return [{
  json: {
    title: rssData.title,
    link: rssData.link,
    pubDate: rssData.pubDate,
    categories: rssData.categories,
    author: rssData.author,
    articleContent: articleContent,
    images: filtered.length > 0 ? filtered.join('\n') : '(No images available)',
  }
}];

const text = $input.first().json.content.parts[0].text;

if (!text) {
  return [{ json: { relevant: false, error: 'Empty Gemini response' } }];
}

// Clean markdown fences if present
let jsonStr = text.trim();
if (jsonStr.startsWith('```')) {
  jsonStr = jsonStr.replace(/^```(?:json)?\n?/, '').replace(/\n?```$/, '');
}
jsonStr = jsonStr.trim();

let parsed;
try {
  parsed = JSON.parse(jsonStr);
} catch (e) {
  const match = jsonStr.match(/\{[\s\S]*\}/);
  if (match) {
    try {
      parsed = JSON.parse(match[0]);
    } catch (e2) {
      return [{ json: { relevant: false, error: 'Failed to parse: ' + e2.message } }];
    }
  } else {
    return [{ json: { relevant: false, error: 'No JSON found in response' } }];
  }
}

if (!parsed.relevant) {
  return [{ json: { relevant: false } }];
}

// Generate slug from original English title
const originalTitle = $('Prepare Gemini Input').first().json.title || '';
const slug = originalTitle
  .toLowerCase()
  .replace(/[^a-z0-9\s-]/g, '')
  .replace(/\s+/g, '-')
  .replace(/-+/g, '-')
  .substring(0, 80)
  .replace(/^-|-$/g, '');

const dateStr = new Date().toISOString().slice(0, 10);
const finalSlug = slug ? dateStr + '-' + slug : dateStr + '-' + Math.random().toString(36).substring(2, 10);

return [{
  json: {
    relevant: true,
    slug: finalSlug,
    title: parsed.title || 'ללא כותרת',
    content: parsed.content || '',
    excerpt: parsed.excerpt || '',
    metaDescription: parsed.metaDescription || parsed.excerpt || '',
    featuredImageUrl: parsed.featuredImageUrl || null,
    category: parsed.category || 'טכנולוגיה',
    tags: Array.isArray(parsed.tags) ? parsed.tags : [],
    author: 'זאפלי',
  }
}];

