// ── HTTP GET buffer (follows redirects) ──
function httpGetBuffer(url, maxRedir) {
  if (!maxRedir) maxRedir = 5;
  return new Promise((resolve, reject) => {
    if (maxRedir <= 0) return reject(new Error('Too many redirects'));
    const mod = url.startsWith('https') ? https : http;
    const req = mod.get(url, {
      headers: { 'User-Agent': 'Mozilla/5.0 (compatible; ZapliBot/1.0)' },
      timeout: 20000
    }, (res) => {
      if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
        let loc = res.headers.location;
        if (loc.startsWith('/')) { const u = new URL(url); loc = u.origin + loc; }
        return httpGetBuffer(loc, maxRedir - 1).then(resolve).catch(reject);
      }
      if (res.statusCode !== 200) return reject(new Error('HTTP ' + res.statusCode));
      const chunks = [];
      res.on('data', c => chunks.push(c));
      res.on('end', () => resolve({
        buffer: Buffer.concat(chunks),
        contentType: (res.headers['content-type'] || 'image/jpeg').split(';')[0].trim()
      }));
    });
    req.on('error', reject);
    req.on('timeout', () => { req.destroy(); reject(new Error('Timeout')); });
  });
}

// ── HTTP GET JSON ──
function httpGetJson(url) {
  return new Promise((resolve, reject) => {
    https.get(url, { timeout: 15000 }, (res) => {
      let data = '';
      res.on('data', c => data += c);
      res.on('end', () => { try { resolve(JSON.parse(data)); } catch (e) { reject(e); } });
    }).on('error', reject);
  });
}

// ── Upload to GCS via S3-compatible API (AWS Sig V4) ──
function s3Upload(buffer, key, contentType) {
  return new Promise((resolve, reject) => {
    const now = new Date();
    const p = (n) => String(n).padStart(2, '0');
    const amzDate = now.getUTCFullYear() + p(now.getUTCMonth() + 1) + p(now.getUTCDate()) + 'T' +
                    p(now.getUTCHours()) + p(now.getUTCMinutes()) + p(now.getUTCSeconds()) + 'Z';
    const dateStamp = amzDate.slice(0, 8);
    const region = 'auto';
    const service = 's3';
    const host = GCS_BUCKET + '.' + GCS_ENDPOINT;
    const canonicalUri = '/' + key;

    const payloadHash = crypto.createHash('sha256').update(buffer).digest('hex');

    const headerLines = [
      'content-type:' + contentType,
      'host:' + host,
      'x-amz-content-sha256:' + payloadHash,
      'x-amz-date:' + amzDate
    ];
    const signedHeaders = 'content-type;host;x-amz-content-sha256;x-amz-date';

    const canonicalRequest = [
      'PUT', canonicalUri, '',
      headerLines.join('\n') + '\n',
      signedHeaders,
      payloadHash
    ].join('\n');

    const scope = dateStamp + '/' + region + '/' + service + '/aws4_request';
    const stringToSign = 'AWS4-HMAC-SHA256\n' + amzDate + '\n' + scope + '\n' +
                         crypto.createHash('sha256').update(canonicalRequest).digest('hex');

    const hmac = (k, d) => crypto.createHmac('sha256', k).update(d).digest();
    const sk = hmac(hmac(hmac(hmac('AWS4' + GCS_SECRET_KEY, dateStamp), region), service), 'aws4_request');
    const sig = crypto.createHmac('sha256', sk).update(stringToSign).digest('hex');

    const auth = 'AWS4-HMAC-SHA256 Credential=' + GCS_ACCESS_KEY + '/' + scope +
                 ', SignedHeaders=' + signedHeaders + ', Signature=' + sig;

    const req = https.request({
      hostname: host, path: canonicalUri, method: 'PUT',
      headers: {
        'Content-Type': contentType,
        'Content-Length': buffer.length,
        'Host': host,
        'x-amz-content-sha256': payloadHash,
        'x-amz-date': amzDate,
        'Authorization': auth
      }
    }, (res) => {
      let d = '';
      res.on('data', c => d += c);
      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          resolve('https://storage.googleapis.com/' + GCS_BUCKET + '/' + key);
        } else {
          reject(new Error('GCS ' + res.statusCode + ': ' + d.substring(0, 300)));
        }
      });
    });
    req.on('error', reject);
    req.write(buffer);
    req.end();
  });
}

