    const result = await httpGetJson(serpUrl);

    if (result.images_results && result.images_results.length > 0) {
      const imgs = result.images_results.slice(0, 3);
      featuredImageUrl = imgs[0].original;
      allUrls.push(featuredImageUrl);
      seen.add(featuredImageUrl);

      for (let i = 1; i < imgs.length; i++) {
        const iUrl = imgs[i].original;
        if (!seen.has(iUrl)) {
          seen.add(iUrl);
          allUrls.push(iUrl);
          const cls = i % 2 === 1 ? 'img-full' : 'img-half';
          content += '<figure class="' + cls + '"><img src="' + iUrl +
                     '" alt="\u05ea\u05de\u05d5\u05e0\u05d4 \u05dc\u05d4\u05de\u05d7\u05e9\u05d4" />' +
                     '<figcaption>\u05ea\u05de\u05d5\u05e0\u05d4 \u05dc\u05d4\u05de\u05d7\u05e9\u05d4</figcaption></figure>';
        }
      }
    }
  } catch (e) {
    // SerpApi unavailable — continue without images
  }
}

// 3. Download each image & upload to GCS
const urlMap = {};
let idx = 0;

for (const originalUrl of allUrls) {
  try {
    const { buffer, contentType } = await httpGetBuffer(originalUrl);
    if (buffer.length < 3000) continue; // skip tiny/tracking images
    const ext = extFromCt(contentType);
    const key = 'articles/' + slug + '/img-' + idx + ext;
    const gcsUrl = await s3Upload(buffer, key, contentType);
    urlMap[originalUrl] = gcsUrl;
    idx++;
  } catch (e) {
    // Failed — keep original URL as fallback
  }
}

// 4. Replace all original URLs with GCS URLs
for (const [orig, gcs] of Object.entries(urlMap)) {
  content = content.split(orig).join(gcs);
  if (featuredImageUrl === orig) featuredImageUrl = gcs;
}

// 5. Remove featured image from body (prevent duplicate)
if (featuredImageUrl) {
  // Find and remove the <figure> block that contains the featured image URL
  let pos = content.indexOf(featuredImageUrl);
  while (pos !== -1) {
    const figStart = content.lastIndexOf('<figure', pos);
    if (figStart !== -1) {
      const figEnd = content.indexOf('</figure>', pos);
      if (figEnd !== -1) {
        content = content.substring(0, figStart) + content.substring(figEnd + '</figure>'.length);
        break; // Only remove the first occurrence
      }
    }
    pos = content.indexOf(featuredImageUrl, pos + 1);
  }
}

return [{
  json: {
    ...item,
    content: content,
    featuredImageUrl: featuredImageUrl
  }
}];

